command:
cargo build -p llama-ffi
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python '..\check_context.py' debug 1
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
cargo test -p llama-model-runtime -p llama-ffi --release --no-fail-fast
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
cargo build -p llama-ffi --release
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python '..\check_context.py' release 1
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
cargo clippy -p llama-model-runtime -p llama-ffi --all-targets -- -D warnings
exit $LASTEXITCODE
